INSERT INTO `competition` (`id`, `title`, `language`, `introduction`, `sign_up_start_time`, `sign_up_end_time`, `start_time`, `end_time`, `official_url`, `image_url`, `status`, `create_time`, `update_time`) VALUES
-- 1. 2024全国大学生数学建模竞赛（国赛-已结束）
(1, '2024年全国大学生数学建模竞赛', 'zh', '全国大学生数学建模竞赛是教育部高等教育司和中国工业与应用数学学会共同主办的面向全国大学生的群众性科技活动，旨在激励学生学习数学的积极性，提高学生建立数学模型和运用计算机技术解决实际问题的综合能力。', '2024-07-15 00:00:00', '2024-08-31 23:59:59', '2024-09-12 08:00:00', '2024-09-15 20:00:00', 'http://www.mcm.edu.cn/', 'https://www.mcm.edu.cn/upload/202407/15/202407151028467896.jpg', 'FINISHED', '2024-06-01 00:00:00', '2024-09-16 00:00:00'),
-- 2. 2024美国大学生数学建模竞赛（美赛-已结束）
(2, '2024 MCM/ICM（美国大学生数学建模竞赛）', 'en', 'The Mathematical Contest in Modeling (MCM) and Interdisciplinary Contest in Modeling (ICM) are international competitions for undergraduate students that challenge teams to clarify, analyze, and propose solutions to open-ended problems.', '2024-01-01 00:00:00', '2024-01-30 23:59:59', '2024-02-01 08:00:00', '2024-02-05 08:00:00', 'https://www.comap.com/undergraduate/contests/mcm/', 'https://www.comap.com/images/mcm_icm_banner_2024.jpg', 'FINISHED', '2023-12-01 00:00:00', '2024-02-06 00:00:00'),
-- 3. 2024全国研究生数学建模竞赛（已结束）
(3, '2024年全国研究生数学建模竞赛', 'zh', '全国研究生数学建模竞赛是面向全国在读研究生的一项学科竞赛活动，旨在培养研究生创新能力、团队协作精神和解决实际问题的能力，促进研究生数学建模教学和科研水平的提升。', '2024-08-01 00:00:00', '2024-09-10 23:59:59', '2024-09-21 08:00:00', '2024-09-25 20:00:00', 'http://cpacm.seu.edu.cn/', 'https://cpacm.seu.edu.cn/upload/202408/05/202408051432109876.png', 'FINISHED', '2024-07-01 00:00:00', '2024-09-26 00:00:00'),
-- 4. 2024江苏省大学生数学建模竞赛（省级-已结束）
(4, '2024年江苏省大学生数学建模竞赛', 'zh', '江苏省大学生数学建模竞赛是省内规模最大、影响力最广的大学生数学建模赛事，旨在选拔优秀参赛队伍代表江苏省参加全国大学生数学建模竞赛，提升省内高校建模教学水平。', '2024-04-01 00:00:00', '2024-05-15 23:59:59', '2024-05-24 08:00:00', '2024-05-27 20:00:00', 'http://mathmodeling.jsnu.edu.cn/', 'http://mathmodeling.jsnu.edu.cn/static/images/2024_comp_banner.jpg', 'FINISHED', '2024-03-01 00:00:00', '2024-05-28 00:00:00'),
-- 5. 2023美赛（历史赛事-已结束）
(5, '2023 MCM/ICM（美国大学生数学建模竞赛）', 'en', 'The 2023 MCM/ICM focused on real-world problems such as climate change and public health, attracting over 60,000 teams from around the world.', '2023-01-02 00:00:00', '2023-01-29 23:59:59', '2023-02-02 08:00:00', '2023-02-06 08:00:00', 'https://www.comap.com/undergraduate/contests/mcm/', 'https://www.comap.com/images/mcm_icm_banner_2023.jpg', 'FINISHED', '2022-11-30 00:00:00', '2023-02-07 00:00:00'),

-- 进行中的赛事（ONGOING）- 模拟省级邀请赛/专项赛
-- 6. 2024年华东地区数学建模秋季邀请赛（进行中）
(6, '2024年华东地区大学生数学建模秋季邀请赛', 'zh', '华东地区数学建模秋季邀请赛是面向华东六省一市高校的专项赛事，旨在补充国赛后的实战训练机会，提升学生建模应用能力。', '2024-10-01 00:00:00', '2024-10-20 23:59:59', '2024-10-25 08:00:00', '2024-10-28 20:00:00', 'http://www.huadongmathmod.com/', 'https://www.huadongmathmod.com/images/2024_autumn_banner.png', 'ONGOING', '2024-09-01 00:00:00', '2024-10-26 00:00:00'),
-- 7. 2024年全国数学建模专项赛（人工智能方向）（进行中）
(7, '2024年全国数学建模专项赛（人工智能方向）', 'zh', '聚焦人工智能领域的数学建模应用，重点考察参赛队伍将机器学习、深度学习模型与实际问题结合的能力，为AI领域建模人才提供专项训练。', '2024-10-05 00:00:00', '2024-10-22 23:59:59', '2024-10-26 08:00:00', '2024-10-29 20:00:00', 'http://www.mcm.edu.cn/special/ai2024/', 'https://www.mcm.edu.cn/upload/202409/20/202409201115324567.jpg', 'ONGOING', '2024-09-10 00:00:00', '2024-10-27 00:00:00'),

-- 即将到来的赛事（UPCOMING）- 2025年主流赛事
-- 8. 2025全国大学生数学建模竞赛（国赛-即将到来）
(8, '2025年全国大学生数学建模竞赛', 'zh', '2025年全国大学生数学建模竞赛将延续往届赛事宗旨，聚焦国家发展、民生保障、科技前沿等领域的实际问题，进一步优化评审标准，提升赛事公平性与专业性。', '2025-07-20 00:00:00', '2025-08-31 23:59:59', '2025-09-11 08:00:00', '2025-09-14 20:00:00', 'http://www.mcm.edu.cn/', 'https://www.mcm.edu.cn/upload/202506/10/202506100912345678.jpg', 'UPCOMING', '2025-05-01 00:00:00', '2025-06-10 00:00:00'),
-- 9. 2025 MCM/ICM（美赛-即将到来）
(9, '2025 MCM/ICM（美国大学生数学建模竞赛）', 'en', 'The 2025 MCM/ICM will introduce new problem categories related to sustainable development and digital economy, welcoming global undergraduate teams to participate.', '2025-01-05 00:00:00', '2025-01-31 23:59:59', '2025-02-06 08:00:00', '2025-02-10 08:00:00', 'https://www.comap.com/undergraduate/contests/mcm/', 'https://www.comap.com/images/mcm_icm_banner_2025.jpg', 'UPCOMING', '2024-11-01 00:00:00', '2024-12-01 00:00:00'),
-- 10. 2025全国研究生数学建模竞赛（即将到来）
(10, '2025年全国研究生数学建模竞赛', 'zh', '2025年全国研究生数学建模竞赛将新增“生物医药建模”专项赛道，鼓励研究生结合学科特色解决生物医药领域的实际问题，推动产学研融合。', '2025-08-05 00:00:00', '2025-09-15 23:59:59', '2025-09-20 08:00:00', '2025-09-24 20:00:00', 'http://cpacm.seu.edu.cn/', 'https://cpacm.seu.edu.cn/upload/202507/05/202507051523456789.png', 'UPCOMING', '2025-06-01 00:00:00', '2025-07-05 00:00:00'),
-- 11. 2025江苏省大学生数学建模竞赛（即将到来）
(11, '2025年江苏省大学生数学建模竞赛', 'zh', '2025年江苏省赛将首次增设“高职高专专项组”，覆盖更多院校类型，同时优化省内分赛区评审机制，提升赛事的普惠性与专业性。', '2025-04-05 00:00:00', '2025-05-20 23:59:59', '2025-05-23 08:00:00', '2025-05-26 20:00:00', 'http://mathmodeling.jsnu.edu.cn/', 'http://mathmodeling.jsnu.edu.cn/static/images/2025_comp_banner.jpg', 'UPCOMING', '2025-03-01 00:00:00', '2025-04-05 00:00:00'),
-- 12. 2025年粤港澳大湾区数学建模挑战赛（即将到来）
(12, '2025年粤港澳大湾区大学生数学建模挑战赛', 'zh', '粤港澳大湾区数学建模挑战赛聚焦湾区发展核心议题，如智慧城市、跨境物流、绿色能源等，旨在培养服务湾区建设的建模人才。', '2025-03-01 00:00:00', '2025-04-15 23:59:59', '2025-04-20 08:00:00', '2025-04-23 20:00:00', 'http://www.gba-mathmod.com/', 'https://www.gba-mathmod.com/images/2025_banner.jpg', 'UPCOMING', '2025-01-15 00:00:00', '2025-02-20 00:00:00');
